```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The session identity is stamped by the host channel; the node never
        // fabricates it. We send exactly once (no retry, to avoid duplicate
        // delivery) and return the channel's own confirmation.
        let confirmation = response_channel::send(&reply.text);

        // Contract: `delivered == true` and a present session id must hold of
        // every output produced. If the channel did not accept the message, or
        // did not identify its session, there is no honest output satisfying
        // the contract — trap rather than forge one.
        if !confirmation.delivered {
            panic!("response channel did not accept the reply");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        confirmation
    }
}

export!(Node);
